import { Context, Effect, Layer } from "effect";

import {
  NotificationChannelRegistry,
  type NotificationPersistInput,
  type NotificationPersistResult,
  type NotificationMessage,
  type NotificationSendInput,
  type NotificationChannel,
} from "./channels";
import { NotificationSendError } from "./schema";

export interface NotificationServiceContract {
  readonly send: (
    input: NotificationSendInput,
  ) => Effect.Effect<
    NotificationPersistResult | undefined,
    NotificationSendError
  >;
}

export interface NotificationPersistenceStoreContract {
  readonly persist: (
    input: NotificationPersistInput,
  ) => Effect.Effect<NotificationPersistResult, NotificationSendError>;
}

/** @deprecated Use NotificationServiceContract. */
export { type NotificationServiceContract as NotificationServiceShape };

export class NotificationPersistenceStore extends Context.Service<
  NotificationPersistenceStore,
  NotificationPersistenceStoreContract
>()("NotificationPersistenceStore") {
  static readonly noopLayer = Layer.succeed(this, {
    persist: () =>
      Effect.succeed({ deliveryIds: [], notificationId: undefined }),
  });

  static readonly layer = (store: NotificationPersistenceStoreContract) =>
    Layer.succeed(this, store);
}

const isStructuredSendInput = (
  input: NotificationSendInput,
): input is Extract<
  NotificationSendInput,
  { readonly persist: NotificationPersistInput }
> => Object.hasOwn(input, "persist");

export class NotificationService extends Context.Service<
  NotificationService,
  NotificationServiceContract
>()("NotificationService", {
  make: Effect.gen(function* () {
    const registry = yield* NotificationChannelRegistry;
    const persistence = yield* NotificationPersistenceStore;

    const dispatch = Effect.fn("NotificationService.dispatch")(
      (message: NotificationMessage) =>
        Effect.gen(function* () {
          for (const [key, payload] of Object.entries(message)) {
            const channels = registry.channels.filter(
              (item) => item.key === key,
            );

            if (channels.length === 0) {
              return yield* new NotificationSendError({
                channel: key,
                message: `No notification channel installed for ${key}`,
              });
            }

            yield* Effect.forEach(channels, (channel) =>
              channel.send(payload, message),
            );
          }
        }),
    );

    const send = Effect.fn("NotificationService.send")(
      (input: NotificationSendInput) =>
        Effect.gen(function* () {
          if (!isStructuredSendInput(input)) {
            yield* dispatch(input);
            return undefined;
          }

          const persisted = yield* persistence.persist(input.persist);
          if (input.message) yield* dispatch(input.message);
          return persisted;
        }),
    );

    return { send };
  }),
}) {
  static readonly layer = Layer.effect(this, this.make);

  static readonly makeLayer = (channels: ReadonlyArray<NotificationChannel>) =>
    this.layer.pipe(
      Layer.provide(NotificationChannelRegistry.layer(channels)),
      Layer.provide(NotificationPersistenceStore.noopLayer),
    );

  static readonly makePersistentLayer = ({
    channels,
    store,
  }: {
    readonly channels: ReadonlyArray<NotificationChannel>;
    readonly store: NotificationPersistenceStoreContract;
  }) =>
    this.layer.pipe(
      Layer.provide(NotificationChannelRegistry.layer(channels)),
      Layer.provide(NotificationPersistenceStore.layer(store)),
    );

  static readonly noopLayer = Layer.succeed(this, {
    send: () => Effect.succeed(undefined),
  });

  static readonly localLayer = this.makeLayer([
    {
      key: "email",
      send: (payload) => Effect.logInfo("[fake email]", payload),
    },
  ]);
}

import { Context, Effect, Layer } from "effect";
import type { Json } from "effect/Schema";

import { NotificationSendError } from "../schema";

export interface NotificationChannels {}

export type NotificationMessage<FallbackPayload = Json> =
  keyof NotificationChannels extends never
    ? Record<string, FallbackPayload>
    : Partial<{
        readonly [Key in keyof NotificationChannels]: NotificationChannels[Key];
      }>;

export interface NotificationChannel<
  Key extends string = string,
  Payload = Json,
> {
  readonly key: Key;
  readonly send: (
    payload: Payload,
    message: NotificationMessage,
  ) => Effect.Effect<void, NotificationSendError>;

  readonly payload?: Payload;
}

export interface NotificationChannelRegistryService {
  readonly channels: ReadonlyArray<NotificationChannel>;
}

export interface NotificationInboxInput {
  readonly description?: string | undefined;
  readonly href?: string | undefined;
  readonly metadata?: Json | undefined;
  readonly title: string;
}

export interface NotificationDeliveryInput {
  readonly channel: string;
  readonly idempotencyKey?: string | undefined;
  readonly maxAttempts?: number | undefined;
  readonly payload: Json;
  readonly payloadVersion?: number | undefined;
  readonly purpose: "transactional" | "notification";
  readonly recipientAddress: string;
  readonly recipientName?: string | undefined;
  readonly recipientUserId?: string | undefined;
  readonly scheduledFor?: Date | undefined;
  readonly template?: string | undefined;
}

export interface NotificationPersistInput {
  readonly deliveries?: ReadonlyArray<NotificationDeliveryInput> | undefined;
  readonly eventKey: string;
  readonly eventVersion?: number | undefined;
  readonly idempotencyKey: string;
  readonly inbox?: NotificationInboxInput | undefined;
  readonly locale?: string | undefined;
  readonly organizationId?: string | undefined;
  readonly recipientUserId?: string | undefined;
  readonly workspaceId?: string | undefined;
}

export interface NotificationPersistResult {
  readonly deliveryIds: ReadonlyArray<string>;
  readonly notificationId: string | undefined;
}

export type NotificationSendInput =
  | NotificationMessage
  | {
      readonly message?: NotificationMessage | undefined;
      readonly persist: NotificationPersistInput;
    };

/** @deprecated Use the domain-owned names without the Shape suffix. */
export {
  type NotificationChannel as NotificationChannelShape,
  type NotificationChannelRegistryService as NotificationChannelRegistryShape,
};

export class NotificationChannelRegistry extends Context.Service<
  NotificationChannelRegistry,
  NotificationChannelRegistryService
>()("NotificationChannelRegistry") {
  static readonly make = (
    ...channels: ReadonlyArray<NotificationChannel>
  ): NotificationChannelRegistryService => ({ channels });

  static readonly layer = (channels: ReadonlyArray<NotificationChannel>) =>
    Layer.succeed(this, this.make(...channels));

  static readonly emptyLayer = Layer.succeed(this, this.make());
}

import { Schema } from "effect";

export const NotificationMessageSchema = Schema.Record(
  Schema.String,
  Schema.Unknown,
).annotate({
  identifier: "NotificationMessage",
  title: "Notification message",
  description:
    "A dynamic notification envelope keyed by channel capability. Installed channels send the payload matching their key.",
  examples: [
    {
      email: {
        to: "user@example.com",
        subject: "Welcome",
        text: "Thanks for signing up.",
      },
      discord: {
        content: "A user signed up.",
      },
    },
  ],
});

export class NotificationSendError extends Schema.TaggedError<NotificationSendError>()(
  "NotificationSendError",
  {
    message: Schema.String,
    channel: Schema.optional(Schema.String),
    error: Schema.optional(Schema.Defect()),
  },
) {}

export type { NotificationMessage, NotificationSendInput } from "./channels";
